const REPO_ROOT = resolve(import.meta.dir, '../..');
const CLI_SCRIPT = join(REPO_ROOT, 't/harness/offline-attestation-verifier.ts');
const WORK_DIR = mkdtempSync(join(tmpdir(), 'de-offline-ts-adv-'));

